 function offerDialog(b){const selected=(b.offers||[]).find(o=>o.id===selectedOfferId);return `<dialog class="novel-offers-dialog" aria-labelledby="novelOffersTitle"><header><div><small>短剧改编 · 版权合同</small><h2 id="novelOffersTitle">${esc(b.title)}</h2></div><button type="button" data-n-action="close-offers" aria-label="关闭版权邀约">×</button></header><div class="novel-offers-list">${selected?`<article class="novel-contract"><button type="button" class="novel-contract-back" data-n-action="offer-list">‹ 返回报价</button><div class="novel-contract-paper"><small>短剧改编权合作意向书 · 模拟合同</small><h3>${esc(b.title)}</h3><p class="novel-contract-intro">甲方：${esc(b.author)}（原著版权方）<br>乙方：${esc(selected.company)}（改编制作方）</p><h4>一、作品与改编方向</h4><p>乙方拟将《${esc(b.title)}》改编为短剧。${esc(selected.direction)}</p>${selected.companyStatus?`<h4>二、制作公司状况</h4><p>${esc(selected.companyStatus.summary)}</p><div class="novel-company-scores"><span>资金 ${selected.companyStatus.funding}/5</span><span>制作 ${selected.companyStatus.production}/5</span><span>发行 ${selected.companyStatus.distribution}/5</span></div><p>主要风险：${esc(selected.companyStatus.risk)}</p>`:''}<h4>三、版权报价</h4><p>改编版权费 <strong>${money(selected.feeCents)}</strong>${b.owner?'；确认签约后计入你的游戏内银行卡。':'。'}</p><h4>四、制作计划</h4><p>计划 ${selected.episodes} 集，拍摄 ${selected.days} 天；制作总预算 ${money(selected.budgetCents)}。</p><h4>五、拟选角色与片酬</h4>${selected.parts.map(part=>`<div class="novel-contract-role"><b>${esc(part.name)}</b><span>${money(part.feeCents)} · ${esc(part.description)}</span></div>`).join('')}<p class="novel-contract-note">本页为游戏内模拟合作意向，确认后将创建短剧项目，并按后续流程选角与制作。</p></div>${button('确认选择这份合同','accept-offer',`data-id="${esc(selected.id)}"`,true)}</article>`:`<div class="novel-contract-list-head"><p>以下报价已保存。打开报价可查看具体合同，再决定是否签约。</p></div>${(b.offers||[]).map(o=>`<article class="novel-offer novel-price-offer"><small>${esc(o.company)}</small><button type="button" class="novel-price-quote" data-n-action="offer-detail" data-id="${esc(o.id)}" aria-label="查看${esc(o.company)}的${money(o.feeCents)}报价与合同"><span>版权报价</span><strong>${money(o.feeCents)}</strong><i aria-hidden="true">›</i></button></article>`).join('')}${b.offers?.length?button('重新获取报价 · API','refresh-offers'):''}`}</div></dialog>`}
 function mountOfferDialog(){const dialog=rt.content.querySelector('.novel-offers-dialog');if(!dialog)return;dialog.addEventListener('cancel',e=>{e.preventDefault();offersOpen=false;dialog.close();dialog.remove()});dialog.addEventListener('click',e=>{if(e.target!==dialog)return;const box=dialog.getBoundingClientRect();if(e.clientX<box.left||e.clientX>box.right||e.clientY<box.top||e.clientY>box.bottom){offersOpen=false;dialog.close();dialog.remove()}});dialog.showModal()}
 function pinProjectNavigation(){
  const studio=rt.content.querySelector('.novel-view-project'),scroll=studio.querySelector('.novel-scroll'),fixed=document.createElement('section');fixed.className='novel-project-fixed';fixed.setAttribute('aria-label','短剧项目导航');
  for(const selector of ['.novel-project-head','.novel-screen','.novel-screen-tabs','.novel-episode-grid']){const node=scroll.querySelector(selector);if(node)fixed.append(node)}
  const categories=scroll.querySelector('.novel-production-categories');if(categories)fixed.append(categories);
  studio.insertBefore(fixed,scroll);
 }
 function productionProgress(p){let percent=0,label='选角招募';if(p.status==='recruiting'){percent=p.responsesDone?20:p.groupId?15:10}else if(p.status==='audition'){label='角色试镜';const accepted=p.applicants.filter(a=>a.accepted).length||p.applicants.length;percent=20+(p.roleAuditionsDone?20:Math.round(20*Math.min(1,p.auditions.length/Math.max(1,accepted))))}else if(p.status==='contracting'){label='演员签约';percent=45+(p.roleContractsDone?10:0)+(p.cast.some(a=>a.user&&a.userDecided)?5:0)}else if(p.status==='filming'){label='拍摄制作';const total=p.productionMode==='episodes'?Math.max(1,p.episodes||1):Math.max(1,Math.min(3,p.episodes||3));const done=p.productionMode==='episodes'?(p.screen?.episodes?.length||0):(p.shoots?.length||0);percent=60+Math.round(30*Math.min(1,done/total))}else if(p.status==='finished'){label='已杀青';percent=95}else if(p.status==='released'){label='已上线';percent=100}else{label=status(p);percent=0}return{percent:Math.max(0,Math.min(100,percent)),label}}
 function progressPanel(p,author,controls,plan){const progress=productionProgress(p),bar=`<div class="novel-project-progress-track" role="progressbar" aria-label="项目完成度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${progress.percent}"><span style="width:${progress.percent}%"></span></div>`;return `<details class="novel-panel novel-project-progress-panel" ${progressExpanded?'open':''}><summary class="novel-progress-summary"><h3>项目进度</h3><div class="novel-progress-compact"><span><i style="width:${progress.percent}%"></i></span><b>${progress.percent}%</b></div><span class="novel-progress-toggle" aria-hidden="true"></span></summary><div class="novel-project-progress-content"><div class="novel-project-progress-label"><span>${esc(progress.label)}</span><small>${esc(author)} 原著</small><strong>${progress.percent}%</strong></div>${bar}${controls}${plan}</div></details>`}
 function productionLayout(p,body){const template=document.createElement('template');template.innerHTML=body;const sections=[...template.content.children].filter(node=>node.matches('section.novel-panel')||node.matches('details.novel-project-progress-panel')),progress=sections.shift();const categories=[['casting','选角'],['auditions','试镜'],['salary','薪酬'],['financiers','资方评价'],['final','最终定角'],['production','拍摄记录']];for(const section of sections){const title=section.querySelector('h3')?.textContent||'';section.dataset.productionSection=/试镜档案/.test(title)?'auditions':/最终定角/.test(title)?'final':/正片与幕后|小说更新/.test(title)?'production':/项目结算/.test(title)?'salary':'casting';section.hidden=section.dataset.productionSection!==productionCategory}
 const salary=`<section class="novel-panel" data-production-section="salary" ${productionCategory==='salary'?'':'hidden'}><header><h3>片酬与结算方式</h3><small>全剧片酬 · 开拍 30% / 杀青 70%</small></header>${p.parts.map(part=>`<article class="novel-salary-row"><strong>${esc(part.name)}</strong><div><b>${money(part.feeCents)}</b>${p.cast?.some(actor=>actor.partId===part.id&&actor.npc&&actor.accepted)?'<small>NPC 演员 · 计入制作预算</small>':`<small>开拍 ${money(Math.floor(part.feeCents*.3))} · 杀青 ${money(part.feeCents-Math.floor(part.feeCents*.3))}</small>`}</div></article>`).join('')}</section>`;
 const review=p.financierReview,financiers=`<section class="novel-panel" data-production-section="financiers" ${productionCategory==='financiers'?'':'hidden'}><header><h3>资方选角评价</h3><small>${p.contributions?.length?'已出资方与制片方意见':'制片公司评估'}</small></header><p class="novel-hint">结合实际试镜、角色适配和制作预算评价，不以出资额替代演技判断。</p>${p.roleAuditionsDone&&['audition','contracting'].includes(p.status)?button(review?'重新评估试镜 · API':'查看资方评价 · API','financier-review'): '<p class="novel-hint">完成角色试镜后可进行评价。</p>'}${review?`<p class="novel-prose">${esc(review.summary)}</p>${review.reviews.map(r=>`<article class="novel-financier-review"><strong>${esc(p.applicants.find(a=>a.actorId===r.actorId)?.actorName||'候选人')} · ${esc(partName(p,r.partId))}</strong><p>${esc(r.opinion)}</p><small>待确认：${esc(r.concern||'无补充')}</small></article>`).join('')}`:''}${investmentMarkup(p)}</section>`;
 const placeholders=[['auditions','试镜记录将在完成表演后显示。'],['final','完成试镜后，在项目进度中敲定最终角色；演员仍需确认出演合约。'],['production','开拍后，这里会保存正片与幕后记录。']].filter(([key])=>!sections.some(section=>section.dataset.productionSection===key)).map(([key,label])=>`<section class="novel-panel" data-production-section="${key}" ${productionCategory===key?'':'hidden'}><p class="novel-hint">${label}</p></section>`).join('');
 if(progress)progress.remove();return `${progress?.outerHTML||''}<nav class="novel-production-categories" aria-label="选角制作分类">${categories.map(([key,label])=>`<button type="button" data-production-category="${key}" aria-pressed="${key===productionCategory}">${label}</button>`).join('')}</nav>${template.innerHTML}${salary}${financiers}${placeholders}`}
 function reader(b){const c=b.chapters[chapter];return c?`<article class="novel-reader"><h2>${esc(c.title)}</h2>${c.content.split(/\n+/).filter(p=>p.trim()).map(p=>`<p>${esc(p.trimStart())}</p>`).join('')}</article>`:empty('暂无章节','返回详情添加章节。')}
