 const plan=['recruiting','audition','contracting'].includes(p.status)&&!p.roleContractsDone&&!p.cast.some(a=>a.userDecided)?`<form class="novel-plan-form" data-n-plan><label>计划集数<input name="episodes" type="number" min="1" max="100" required value="${p.episodes}"></label><label>每集参考时长<select name="minutes">${[5,10,15,20,25,30].map(m=>`<option value="${m}" ${m===(p.episodeMinutes||5)?'selected':''}>${m} 分钟</option>`).join('')}</select></label><button class="novel-action" ${busy?'disabled':''}>保存计划</button></form>`:'';
