 host.querySelectorAll('[data-story-person],[data-story-link]').forEach(field=>{const update=()=>{if(!draft)return;const key=field.dataset.storyField;if(field.hasAttribute('data-story-person')){const person=draft.storyCast?.find(c=>c.id===field.dataset.storyPerson);if(person)person[key]=field.value}else{const link=draft.storyRelations?.[Number(field.dataset.storyLink)];if(link)link[key]=field.value}delete draft.storyState};field.addEventListener('input',update);field.addEventListener('change',()=>{update();render()})});
