 host.querySelector('[data-n-editor]')?.addEventListener('submit',e=>{e.preventDefault();if(busy)return;const f=e.currentTarget,values=Object.fromEntries(new FormData(f)),editing={...draft};let savedBookId=bid;void task('正在保存作品…',async()=>{await mutate((next,s)=>{if(editing.newChapter){if(editing.chapterId){const b=C.book(s,bid),c=b.chapters.find(c=>c.id===editing.chapterId);if(!b.owner||!c)throw Error('章节已不存在');if(!values.chapterTitle.trim()||!values.content.trim())throw Error('章节标题和正文不能为空');Object.assign(c,{title:C.text(values.chapterTitle,100),content:C.text(values.content,16000)});delete b.storyState;b.updatedAt=Date.now();C.bump(s)}else C.appendChapter(s,bid,{title:values.chapterTitle,content:values.content})}else if(editing.id){const b=C.book(s,editing.id);if(!b.owner)throw Error('只能编辑自己的作品');const setup=C.characterSetup(editing),changedSetting=b.genre!==values.genre||(b.premise||'')!==C.text(values.premise,2000)||JSON.stringify(b.storyCast||[])!==JSON.stringify(setup.storyCast)||JSON.stringify(b.storyRelations||[])!==JSON.stringify(setup.storyRelations);if(!values.title?.trim()||!values.synopsis?.trim())throw Error('请填写书名和简介');if(!C.genres.includes(values.genre)||values.genre==='全部')throw Error('请选择小说题材');Object.assign(b,{title:C.text(values.title,80),author:C.text(values.author,40),genre:values.genre,synopsis:C.text(values.synopsis,2000),premise:C.text(values.premise,2000),...setup,updatedAt:Date.now()});if(changedSetting)delete b.storyState;C.bump(s)}else{const b=C.createBook(s,{...values,storyCast:editing.storyCast||[],storyRelations:editing.storyRelations||[],storyState:editing.storyState,chapters:editing.chapters||[]});savedBookId=b.id}});bid=savedBookId;view='book';draft=null})});
